<?php
namespace Dth\Crm\Services; use Dth\Crm\Models\{Lead,LeadActivity};
final class LeadActivityService {public function record(Lead $lead,array $d):LeadActivity{$a=LeadActivity::create(['lead_id'=>$lead->id,'agent_profile_id'=>$d['agent_profile_id']??$lead->assigned_agent_profile_id,'type'=>$d['type']??'note','status'=>$d['status']??'completed','subject'=>$d['subject']??null,'content'=>$d['content']??null,'outcome'=>$d['outcome']??null,'activity_at'=>$d['activity_at']??now(),'next_follow_up_at'=>$d['next_follow_up_at']??null,'metadata'=>$d['metadata']??[]]);$q=$lead->qualification;if($q){$updates=['last_contacted_at'=>$a->activity_at];if(!$q->first_contacted_at)$updates['first_contacted_at']=$a->activity_at;if($a->next_follow_up_at){$updates['next_follow_up_at']=$a->next_follow_up_at;if(in_array($q->status,['assigned','contacting'],true))$updates['status']='follow_up';}elseif($q->status==='assigned')$updates['status']='contacting';$q->update($updates);}return $a;}}
